const fonts=['Vazirmatn','Tahoma','Arial'];
export function normalizeTextStyles(input,strict=true){const fail=()=>{if(strict)throw Object.assign(new Error('invalid_site_text_style'),{status:400});};if(input===undefined)return {};if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length>300){fail();return {};}const out={};for(const [key,value]of Object.entries(input)){if(!/^(?:field|page|card|faq):[A-Za-z0-9_:/.-]{1,174}$/.test(key)||!value||typeof value!=='object'||Array.isArray(value)){fail();continue;}const style={};for(const prop of Object.keys(value)){const v=value[prop];if(prop==='font'&&fonts.includes(v))style.font=v;else if(prop==='size'&&Number.isFinite(v)&&v>=8&&v<=96)style.size=v;else if(prop==='color'&&typeof v==='string'&&/^#[a-f0-9]{6}$/i.test(v))style.color=v;else fail();}out[key]=style;}return out;}
export function styleSiteText(html,styles={},pathname='/'){const safe=normalizeTextStyles(styles,false);const occurrences=new Map();const fingerprint=text=>{let hash=2166136261;for(const char of text)hash=Math.imul(hash^char.charCodeAt(0),16777619);return (hash>>>0).toString(16);};return html.replace(/<body[\s\S]*<\/body>/,body=>{const fieldCounts=new Map(),fieldIndexes=new Map();for(const match of body.matchAll(/data-site-field="([^"]+)"/g))fieldCounts.set(match[1],(fieldCounts.get(match[1])||0)+1);return body.replace(/<(h[1-6]|p|span|b|strong|li|label|a)(\s[^>]*?)?>/g,(tag,name,attributes='',offset)=>{const content=body.slice(offset+tag.length,body.indexOf('</'+name+'>',offset+tag.length)).replace(/<[^>]*>/g,'').slice(0,500),signature=name+':'+fingerprint(content),count=occurrences.get(signature)||0;occurrences.set(signature,count+1);const existing=attributes.match(/data-site-style="([^"]+)"/),field=attributes.match(/data-site-field="([^"]+)"/),key=existing?.[1]||(field?'field:'+field[1]+((fieldCounts.get(field[1])||0)>1?':'+(fieldIndexes.get(field[1])||0):''):'page:'+pathname+':'+signature+':'+count);if(field)fieldIndexes.set(field[1],(fieldIndexes.get(field[1])||0)+1);if(!/^[A-Za-z0-9_:/.-]{1,180}$/.test(key))return tag;const s=safe[key],css=s?[s.font&&'font-family:'+s.font,s.size&&'font-size:'+s.size+'px',s.color&&'color:'+s.color].filter(Boolean).join(';'):'';const hasStyle=/\sstyle="/.test(attributes);if(css&&hasStyle)attributes=attributes.replace(/\sstyle="([^"]*)"/,(_,previous)=>' style="'+previous+';'+css+'"');return '<'+name+attributes+(existing?'':' data-site-style="'+key+'"')+(css&&!hasStyle?' style="'+css+'"':'')+'>';});});}
